//! `RecipeBookMenu.handlePlacement` of the real `InventoryMenu` against vanilla (fixture generated by
//! `scripts/golden-recipes.sh` from `fixtures/PlaceRecipeGolden.java`): random inventories/grids, recipe book placement with
//! and without "use max items", ghost recipes, clearing the grid back into the inventory, and the result slot recompute and
//! its packets after every grid change.

use crate::common;

use mc_core::ident::Identifier;
use mc_data::Item;
use mc_game::server::level::ServerLevel;
use mc_game::world::container::Container;
use mc_game::world::entity::equipment::EquipmentSlot;
use mc_game::world::entity::player::inventory::Inventory;
use mc_game::world::inventory::*;
use mc_game::world::item::ItemStack;
use mc_game::world::item::crafting::*;
use mc_world::level_storage::WorldDataConfiguration;
use std::cell::RefCell;
use std::rc::Rc;

fn st(s: &ItemStack) -> String {
    if s.is_empty() {
        "-".into()
    } else {
        format!(
            "{}x{}",
            s.item().name().trim_start_matches("minecraft:"),
            s.count()
        )
    }
}

struct TestPlayer {
    inv: Inventory,
    creative: bool,
    events: Vec<String>,
    /// The level the recipes are looked up in (the Java fake level serves the real `RecipeManager`).
    level: ServerLevel,
}

impl MenuPlayer for TestPlayer {
    fn registries(&self) -> mc_game::registry::RegistryAccess {
        self.level.registries.clone()
    }
    fn level(&mut self) -> Option<&mut ServerLevel> {
        Some(&mut self.level)
    }
    fn level_ref(&self) -> Option<&ServerLevel> {
        Some(&self.level)
    }
    fn entity_id(&self) -> i32 {
        0
    }
    fn inventory(&self) -> &Inventory {
        &self.inv
    }
    fn inventory_mut(&mut self) -> &mut Inventory {
        &mut self.inv
    }
    fn has_infinite_materials(&self) -> bool {
        self.creative
    }
    fn is_creative(&self) -> bool {
        self.creative
    }
    fn is_spectator(&self) -> bool {
        false
    }
    fn drop(&mut self, stack: ItemStack, thrown: bool, prediction: Prediction) {
        let p = if prediction == Prediction::Predicted {
            "PREDICTED"
        } else {
            "SERVER_ONLY"
        };
        self.events
            .push(format!("DROP {} {thrown} {p}", st(&stack)));
    }
    fn on_equip_item(&mut self, _slot: EquipmentSlot, _old: &ItemStack, _new: &ItemStack) {}
    fn is_within_block_interaction_range(
        &self,
        _pos: mc_core::pos::BlockPos,
        _buffer: f64,
    ) -> bool {
        false
    }
    fn send_inventory_slot_update(&mut self, _slot: usize, _stack: ItemStack) {}
}

/// Records the packets the menu sends past the broadcast cycle (`ClientboundContainerSetSlotPacket`).
struct Sync(Rc<RefCell<Vec<String>>>);

impl ContainerSynchronizer for Sync {
    fn send_initial_data(
        &mut self,
        _id: i32,
        _state_id: i32,
        _items: Vec<ItemStack>,
        _carried: ItemStack,
        _data: &[i32],
    ) {
    }
    fn send_slot_change(&mut self, _id: i32, state_id: i32, slot: usize, stack: ItemStack) {
        self.0
            .borrow_mut()
            .push(format!("SYNC slot {state_id} {slot} {}", st(&stack)));
    }
    fn send_carried_change(&mut self, _stack: ItemStack) {}
    fn send_data_change(&mut self, _id: i32, _data_id: usize, _value: i32) {}
    fn create_slot(&self) -> RemoteSlot {
        RemoteSlot::new_synchronized()
    }
}

fn mk(name: &str, count: i32) -> ItemStack {
    ItemStack::with_count(
        Item::by_name(name).unwrap_or_else(|| panic!("item {name}")),
        count,
    )
}

#[test]
fn place_recipe_matches_vanilla() {
    let _s = common::SERIAL.lock().unwrap_or_else(|e| e.into_inner());
    let dir = tempfile::tempdir().unwrap();
    let (_, stem) = common::load_world(
        &dir.path().join("world"),
        WorldDataConfiguration::DEFAULT,
        true,
    )
    .unwrap();
    let manager = stem
        .data_pack_resources
        .listener::<RecipeManager>()
        .expect("recipe manager")
        .clone();
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/place_recipe_golden.txt"
    ))
    .unwrap();

    let new_player = |creative: bool| {
        let mut level = ServerLevel::detached(Identifier::parse("minecraft:overworld").unwrap());
        level.registries = stem.registries.composite_access().clone();
        level.shared.set_recipe_manager(manager.clone());
        TestPlayer {
            inv: Inventory::new(),
            creative,
            events: Vec::new(),
            level,
        }
    };
    let sync = Rc::new(RefCell::new(Vec::new()));
    let mut player = new_player(false);
    let mut menu = InventoryMenu::new(true);
    let mut ours: Vec<String> = Vec::new();
    let (mut places, mut ghosts) = (0, 0);
    let mut lines = text.lines().peekable();
    let mut op_no = 0;
    while let Some(line) = lines.next() {
        let Some(op) = line.strip_prefix("OP ") else {
            panic!("unexpected line {line}")
        };
        let mut expected: Vec<&str> = Vec::new();
        while let Some(next) = lines.peek() {
            if next.starts_with("OP ") {
                break;
            }
            expected.push(lines.next().unwrap());
        }
        op_no += 1;
        let words: Vec<&str> = op.split(' ').collect();
        let mut action = "-".to_owned();
        match words[0] {
            "scenario" => {
                player = new_player(words[2] == "creative=true");
                menu = InventoryMenu::new(true);
                menu.base_mut()
                    .set_synchronizer(Box::new(Sync(sync.clone())), &mut player);
                sync.borrow_mut().clear();
                continue;
            }
            "inv" => player.inv.set_item(
                words[1].parse().unwrap(),
                mk(words[2], words[3].parse().unwrap()),
            ),
            "grid" => {
                let stack = mk(words[2], words[3].parse().unwrap());
                menu.base_mut()
                    .with_slot(&mut player, words[1].parse().unwrap(), |s, e| {
                        s.set(e, stack)
                    });
                menu.flush_container_events(&mut player);
            }
            "clearinv" => (0..36).for_each(|i| player.inv.set_item(i, ItemStack::empty())),
            "place" => {
                let holder = manager
                    .by_key(&Identifier::parse(words[1]).unwrap())
                    .expect("recipe")
                    .clone();
                let creative = player.creative;
                action =
                    match menu.handle_placement(&mut player, words[2] == "true", creative, &holder)
                    {
                        PostPlaceAction::Nothing => {
                            places += 1;
                            "NOTHING"
                        }
                        PostPlaceAction::PlaceGhostRecipe => {
                            ghosts += 1;
                            "PLACE_GHOST_RECIPE"
                        }
                    }
                    .to_owned();
            }
            other => panic!("unknown op {other}"),
        }
        ours.clear();
        ours.push(format!("OUT action {action}"));
        let slot_items: Vec<ItemStack> = (0..5)
            .map(|i| {
                menu.base_mut()
                    .with_slot(&mut player, i, |s, e| s.get_item(e))
            })
            .collect();
        ours.push(format!(
            "OUT grid {}",
            slot_items[1..].iter().map(st).collect::<Vec<_>>().join(" ")
        ));
        ours.push(format!("OUT result {}", st(&slot_items[0])));
        let mut inv = String::from("OUT inv");
        for i in 0..player.inv.get_container_size() {
            let it = player.inv.get_item(i);
            if !it.is_empty() {
                inv += &format!(" {i}:{}", st(it));
            }
        }
        ours.push(inv);
        ours.extend(
            std::mem::take(&mut player.events)
                .into_iter()
                .map(|e| format!("OUT {e}")),
        );
        ours.extend(
            std::mem::take(&mut *sync.borrow_mut())
                .into_iter()
                .map(|e| format!("OUT {e}")),
        );
        assert_eq!(ours, expected, "op #{op_no}: {op}");
    }
    eprintln!("placements: {places}, ghost recipes: {ghosts}");
    assert!(places > 50 && ghosts > 50);
    stem.close();
}
